function signedJson(envelope,key){
 if(typeof envelope?.payload!=='string'||typeof envelope?.signature!=='string'||envelope.payload.length>1500000)throw Error('Archivo de actualizacion invalido.');
 const data=Buffer.from(envelope.payload,'base64');
 if(!crypto.verify(null,data,key,Buffer.from(envelope.signature,'base64')))throw Error('La actualizacion no esta firmada por Blu.');
