function verifyUpdate(envelope,key,current){
 const u=signedJson(envelope,key);parts(u.version);
 if(u.kind!=='blu-studio-app'||!/^[a-f0-9]{64}$/i.test(u.sha256)||new URL(u.url).protocol!=='https:')throw Error('Actualizacion incompatible o sin SHA256.');
