 if(!update.available)throw Error('Esta version ya esta instalada.');
 const dir=path.join(root,'updates',update.version);await fs.mkdir(dir,{recursive:true});
 const file=path.join(dir,'BluStudio-Launcher.exe');
 try{if(await hash(file)===update.sha256.toLowerCase())return file;}catch(e){if(e.code!=='ENOENT')throw e;}
 await fs.rm(file,{force:true});status('Descargando actualizacion de la app...',null);await download(update.url,file,update.sha256);
