 if((Get-FileHash -LiteralPath $d.source -Algorithm SHA256).Hash -ine $d.expectedHash){throw 'El archivo de actualizacion cambio. No se reemplazo la app.'}
 $done=$false
 for($i=0;$i -lt 45;$i++){
  try{
   Copy-Item -LiteralPath $d.source -Destination $staged -Force
   if((Get-FileHash -LiteralPath $staged -Algorithm SHA256).Hash -ine $d.expectedHash){throw 'SHA256 incorrecto.'}
   if(Test-Path -LiteralPath $backup){Remove-Item -LiteralPath $backup -Force}
   [IO.File]::Replace($staged,$d.target,$backup)
   $done=$true;break
