 }
 if(!$done){throw 'No se pudo reemplazar el EXE. Se conserva la app anterior. Cierra otras instancias y copia manualmente la descarga.'}
 $p=New-Object Diagnostics.ProcessStartInfo
 $p.FileName=$d.target;$p.UseShellExecute=$true
 [Diagnostics.Process]::Start($p) | Out-Null
