const fs=require('node:fs');const path=require('node:path');const {verifyMods}=require('./pack.cjs');
async function guardMods(pack,instance,onViolation=()=>{},{pollMs=30000}={}){
 await verifyMods(pack,instance);
 let failure=null,closed=false,checking=false,pending=false,timer=null,interval=null,watchers=[];
 function fail(error){if(closed||failure)return;failure='Se detecto un cambio no autorizado en el pack. Se bloqueo la partida. '+error.message;try{onViolation(failure);}catch{}}
 async function check(){
  if(closed||failure)return false;if(checking){pending=true;return true;}checking=true;
  try{do{pending=false;await verifyMods(pack,instance);}while(pending&&!closed&&!failure);return true;}
  catch(e){fail(e);return false;}finally{checking=false;}
 }
 function schedule(){if(closed||failure)return;clearTimeout(timer);timer=setTimeout(check,120);timer.unref?.();}
 function close(){if(closed)return;closed=true;clearTimeout(timer);clearInterval(interval);for(const watcher of watchers)watcher.close();}
 try{
  for(const folder of ['mods','resourcepacks','shaderpacks']){const watcher=fs.watch(path.join(instance,folder),schedule);watcher.on('error',fail);watchers.push(watcher);}
  if(pollMs>0){interval=setInterval(check,pollMs);interval.unref?.();}
  if(!await check()){close();throw Error(failure);}
  return {check,close,get failure(){return failure;}};
