function createAutoUpdater({canRun,check,install,onError=()=>{}}){
 let running=false;
 return async function tick(){
  if(running||!canRun())return false;
  running=true;
  try{
   const update=await check();
   if(!update?.available||!canRun())return false;
   return await install(update);
  }catch(error){onError(error);return false;}finally{running=false;}
 };
}
module.exports={createAutoUpdater};

