const path=require('node:path');
const ID='studio.blu.launcher';
function shortcutScript({link,target}){
 const data=Buffer.from(JSON.stringify({link,target,cwd:path.win32.dirname(target),id:ID}),'utf8').toString('base64');
 return `$ErrorActionPreference='Stop'
$d=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('${data}')) | ConvertFrom-Json
$ws=New-Object -ComObject WScript.Shell
$s=$ws.CreateShortcut($d.link)
$s.TargetPath=$d.target
$s.WorkingDirectory=$d.cwd
$s.IconLocation=$d.target+',0'
$s.Description='Abrir Blu Studio Launcher'
$s.Save()
if(!(Test-Path -LiteralPath $d.link)){throw 'No se pudo crear el acceso directo.'}
`;
}
async function ensureDesktopShortcut({platform,packaged,executable,desktop,shell,fs,fallback}){
 if(platform!=='win32'||!packaged)return 'skipped';
 if(typeof executable!=='string'||!path.win32.isAbsolute(executable)||path.win32.extname(executable).toLowerCase()!=='.exe')return 'skipped';
 const link=path.win32.join(desktop,'Blu Studio.lnk');
 const options={target:executable,cwd:path.win32.dirname(executable),description:'Abrir Blu Studio Launcher',icon:executable,iconIndex:0,appUserModelId:ID};
 let exists=false;
 try{await fs.lstat(link);exists=true;}catch(e){if(e.code!=='ENOENT')throw e;}
 if(exists){
  let current;try{current=shell.readShortcutLink(link);}catch{return 'preserved';}
  if(current.appUserModelId!==ID&&current.description!=='Abrir Blu Studio Launcher')return 'preserved';
  if(typeof current.target==='string'&&current.target.toLowerCase()===executable.toLowerCase())return 'exists';
 }
 let written=false;try{written=shell.writeShortcutLink(link,exists?'update':'create',options);}catch{}
 if(!written&&fallback){await fallback(shortcutScript({link,target:executable}));await fs.lstat(link);written=true;}
 if(!written)throw Error('Windows no permitio crear el acceso directo. Puedes reintentarlo desde Ajustes.');
 return exists?'updated':'created';
}
module.exports={ensureDesktopShortcut,shortcutScript};

