async function authenticateSavedSession({encrypted,decrypt,auth,getProfile}){
 const xbox=await auth.refresh(decrypt(encrypted));
 const mc=await xbox.getMinecraft();
 if(mc.isDemo())throw Error('Esta cuenta no tiene Minecraft Java.');
 const profile=await getProfile(mc.mcToken);
 if(!profile?.id)throw Error('No se pudo verificar la cuenta de Minecraft.');
 mc.profile=profile;
 return {xbox,mc,profile};
}
module.exports={authenticateSavedSession};

