const presets={gold:['#e7c681','#0c1011','#121819'],emerald:['#69d9aa','#091311','#10201b'],violet:['#bd9aff','#100d18','#1b1628'],ice:['#83d5ff','#0a121b','#142332']};
for(const b of document.querySelectorAll('[data-preset]'))b.addEventListener('click',()=>{const [accent,background,panel]=presets[b.dataset.preset];$('themeAccent').value=accent;$('themeBackground').value=background;$('themePanel').value=panel;paintThemePreview();$('themeSavedHint').textContent='Cambios sin guardar';});
action('saveTheme',async()=>{paint(await call('saveTheme',readTheme()));$('themeSavedHint').textContent='Guardado en este PC';notify('Diseño guardado. Exporta para compartirlo con todos.');});
action('exportTheme',async()=>{if(await call('exportTheme',readTheme()))notify('Diseño exportado. Sube launcher-theme.json a la raíz de GitHub.');});
action('resetTheme',async()=>{if(confirm('¿Restablecer el logo, fondo y estilo originales?')){paint(await call('resetTheme'));notify('Diseño original restaurado.');}});
for(const kind of ['Logo','Banner','StudioLogo']){const key=kind==='StudioLogo'?'studioLogo':kind.toLowerCase();action('chooseTheme'+kind,async()=>{const image=await call('themeImage',key);if(image){themeDraft[key]=image;paintThemePreview();$('themeSavedHint').textContent='Imagen lista · sin guardar';}});action('clearTheme'+kind,()=>{themeDraft[key]=null;paintThemePreview();$('themeSavedHint').textContent='Cambios sin guardar';});}
action('openThemeGitHub',()=>call('adminGitHub','theme'));action('openModsGitHub',()=>call('adminGitHub','mods'));action('openActionsGitHub',()=>call('adminGitHub','actions'));action('copyServer',async()=>{await call('copyServer');notify('Dirección del servidor copiada.');});

function layerSource(layer){return layer.image==='client'?'assets/client-logo.png':layer.image;}
function activeLayer(){return themeDraft?.layers?.find(l=>l.id===selectedLayerId)||null;}
function layerChanged(){renderImageLayers(readTheme());refreshLayerControls();$('layerHint').textContent='Cambios sin guardar';$('themeSavedHint').textContent='Cambios sin guardar';}
function setLayerStyle(node,layer,index){node.style.left=layer.x+'%';node.style.top=layer.y+'%';node.style.width=layer.width+'%';node.style.opacity=layer.opacity/100;node.style.transform='translate(-50%,-50%) rotate('+layer.rotation+'deg)';node.style.zIndex=String(index+1);}
function renderImageLayers(theme){
 const containers={banner:$('bannerLayers'),home:$('homeLayers'),sidebar:$('sidebarLayers')},layers=theme.layers||[],ids=new Set(layers.map(l=>l.id));
 for(const [id,node] of layerNodes)if(!ids.has(id)){node.remove();layerNodes.delete(id);}
 document.body.classList.toggle('editingLayers',editingLayers&&!!state?.isAdmin);
 layers.forEach((layer,index)=>{const parent=containers[layer.area];if(!parent)return;let node=layerNodes.get(layer.id);
 if(!node){node=document.createElement('div');node.dataset.layerId=layer.id;const img=document.createElement('img');img.draggable=false;node.append(img);const tag=document.createElement('span');tag.className='layerTag';node.append(tag);const grip=document.createElement('span');grip.className='layerResize';grip.title='Arrastra para cambiar tamaño';node.append(grip);node.addEventListener('pointerdown',event=>beginLayerDrag(event,node,layer.id,event.target.classList.contains('layerResize')));layerNodes.set(layer.id,node);}
 node.className='imageLayer'+(layer.id===selectedLayerId?' selected':'');node.setAttribute('aria-label',layer.name);setLayerStyle(node,layer,index);const img=node.querySelector('img'),src=layerSource(layer);if(img.getAttribute('src')!==src)img.src=src;img.alt=layer.name;node.querySelector('.layerTag').textContent=layer.name;if(node.parentElement!==parent)parent.append(node);
 });
}
function refreshLayerControls(){
 const select=$('selectedLayer'),layers=themeDraft?.layers||[];select.replaceChildren();for(const layer of layers){const option=document.createElement('option');option.value=layer.id;option.textContent=layer.name;select.append(option);}if(!layers.some(l=>l.id===selectedLayerId))selectedLayerId=layers[0]?.id||'';select.value=selectedLayerId;const layer=activeLayer();for(const id of ['layerArea','layerWidth','layerOpacity','layerRotation','layerTopRight','layerBottomLeft','layerForward','duplicateLayer','removeLayer'])$(id).disabled=!layer;
 if(layer){$('layerArea').value=layer.area;$('layerWidth').value=layer.width;$('layerOpacity').value=layer.opacity;$('layerRotation').value=layer.rotation;}
}
function setLayerEditing(enabled){
 editingLayers=!!enabled&&!!state?.isAdmin;$('layerEditorBar').classList.toggle('hidden',!editingLayers);$('startLayerEditor').textContent=editingLayers?'Terminar edición':'Colocar imágenes';
 if(editingLayers){selectPage('play');renderImageLayers(readTheme());refreshLayerControls();notify('Selecciona una imagen y arrástrala. Guarda cuando termines.');}
 else{call('editingTheme',!$('admin').classList.contains('hidden')||!$('appearance').classList.contains('hidden')).catch(()=>{});renderImageLayers(themeDraft?readTheme():state?.theme||{});}
}
function beginLayerDrag(event,node,id,resizing){
 if(!editingLayers||!state?.isAdmin||busy||event.button!==0)return;event.preventDefault();event.stopPropagation();selectedLayerId=id;document.querySelectorAll('.imageLayer').forEach(n=>n.classList.toggle('selected',n.dataset.layerId===id));refreshLayerControls();const layer=activeLayer(),rect=node.parentElement.getBoundingClientRect(),start={px:event.clientX,py:event.clientY,x:layer.x,y:layer.y,width:layer.width};node.setPointerCapture(event.pointerId);
 const move=e=>{if(resizing)layer.width=Math.round(Math.max(2,Math.min(100,start.width+(e.clientX-start.px)*100/rect.width))*10)/10;else{layer.x=Math.round(Math.max(0,Math.min(100,start.x+(e.clientX-start.px)*100/rect.width))*10)/10;layer.y=Math.round(Math.max(0,Math.min(100,start.y+(e.clientY-start.py)*100/rect.height))*10)/10;}setLayerStyle(node,layer,themeDraft.layers.indexOf(layer));$('layerWidth').value=layer.width;$('layerHint').textContent='Cambios sin guardar';$('themeSavedHint').textContent='Cambios sin guardar';};
 const end=()=>{node.removeEventListener('pointermove',move);node.removeEventListener('pointerup',end);node.removeEventListener('pointercancel',end);};node.addEventListener('pointermove',move);node.addEventListener('pointerup',end);node.addEventListener('pointercancel',end);
}
function alignLayer(right){const l=activeLayer();if(!l)return;const node=Array.from(document.querySelectorAll('.imageLayer')).find(n=>n.dataset.layerId===l.id),parent=node?.parentElement.getBoundingClientRect(),img=node?.querySelector('img');const aspect=img?.naturalWidth?img.naturalHeight/img.naturalWidth:1;const height=parent?l.width*parent.width*aspect/parent.height:l.width;l.x=Math.max(2,Math.min(98,right?98-l.width/2:2+l.width/2));l.y=Math.max(2,Math.min(98,right?4+height/2:96-height/2));layerChanged();}
action('startLayerEditor',()=>setLayerEditing(!editingLayers));action('openLayerEditor',()=>setLayerEditing(true));action('closeLayerEditor',()=>setLayerEditing(false));
action('addImageLayer',async()=>{if((themeDraft.layers?.length||0)>=10)throw Error('Puedes poner hasta 10 imágenes.');const image=await call('themeImage','layer');if(!image)return;const id='image-'+crypto.randomUUID();themeDraft.layers.push({id,name:'Imagen '+(themeDraft.layers.length+1),image,area:$('layerArea').value||'banner',x:50,y:50,width:18,rotation:0,opacity:100});selectedLayerId=id;layerChanged();});
$('selectedLayer').addEventListener('change',()=>{selectedLayerId=$('selectedLayer').value;renderImageLayers(readTheme());refreshLayerControls();});$('layerArea').addEventListener('change',()=>{const l=activeLayer();if(l){l.area=$('layerArea').value;l.x=50;l.y=50;layerChanged();}});
for(const [id,key] of [['layerWidth','width'],['layerOpacity','opacity'],['layerRotation','rotation']])$(id).addEventListener('input',()=>{const l=activeLayer();if(!l)return;const n=Number($(id).value);if(!Number.isFinite(n))return;l[key]=Math.max(key==='rotation'?-180:key==='width'?2:0,Math.min(key==='rotation'?180:100,n));layerChanged();});
action('layerTopRight',()=>alignLayer(true));action('layerBottomLeft',()=>alignLayer(false));action('removeLayer',()=>{themeDraft.layers=themeDraft.layers.filter(l=>l.id!==selectedLayerId);layerChanged();});action('layerForward',()=>{const l=activeLayer();if(l){themeDraft.layers=themeDraft.layers.filter(v=>v!==l);themeDraft.layers.push(l);layerChanged();}});action('duplicateLayer',()=>{const l=activeLayer();if(!l||themeDraft.layers.length>=10)return;const copy={...l,id:'image-'+crypto.randomUUID(),name:l.name+' copia',x:Math.min(95,l.x+4),y:Math.min(95,l.y+4)};copy.name=copy.name.slice(0,40);themeDraft.layers.push(copy);selectedLayerId=copy.id;layerChanged();});
action('saveLayers',async()=>{paint(await call('saveTheme',readTheme()));$('layerHint').textContent='Diseño guardado en este PC';notify('Imágenes guardadas. Exporta el diseño para compartirlo.');});action('exportLayers',async()=>{if(await call('exportTheme',readTheme()))notify('Sube launcher-theme.json a la raíz de GitHub para compartirlo.');});
call('state').then(paint).catch(()=>{});

