// Keep transient copies made while editing the Windows PE out of the payload.
const path=require('node:path');
const archive=require('app-builder-lib/out/targets/archive');
const original=archive.archive;
archive.archive=async(format,out,dir,options={})=>{const result=await original(format,out,dir,{...options,excluded:[...(options.excluded||[]),'.BluStudio-Launcher.exe*']});if(process.env.BLU_PACKAGE_AUDIT)require('node:fs').copyFileSync(out,process.env.BLU_PACKAGE_AUDIT);return result;};
const {build}=require('electron-builder');
const {Platform}=require('app-builder-lib');
const {Arch}=require('builder-util');
const args=process.argv.slice(2),value=key=>{const at=args.indexOf(key);return at<0?undefined:path.resolve(args[at+1]);};
build({projectDir:__dirname,targets:Platform.WINDOWS.createTarget('portable',Arch.x64),prepackaged:value('--prepackaged'),config:value('--output')?{directories:{output:value('--output')}}:undefined}).catch(error=>{console.error(error.message);process.exitCode=1;});
